{
  "analysis": "We have partial OCR output with many prompt lines visible. I need see the full set of frame markers and command lines from the partial output, and determine how far the OCR progressed. Then I can switch to a faster cropped prompt-line OCR for all frames to get complete coverage.",
  "plan": "Check the last frame marker in the partial OCR and view the full list of prompt lines. Then create a faster pipeline that crops only the prompt/input line from each dense frame and OCRs those small images.",
  "commands": [
    {
      "keystrokes": "grep '^===' /app/dense_ocr.txt | tail -5; echo '---'; grep -n '^>' /app/dense_ocr.txt | sed -n '1,400p'\n",
      "duration": 0.1
    },
    {
      "keystrokes": "mkdir -p /app/prompts && for f in /app/dense/frame_*.png; do b=$(basename \"$f\" .png); ffmpeg -hide_banner -loglevel error -y -i \"$f\" -vf \"crop=900:32:5:585\" \"/app/prompts/${b}.png\"; done\n",
      "duration": 10.0
    },
    {
      "keystrokes": "ls /app/prompts | wc -l; tesseract /app/prompts/frame_0001.png stdout --psm 7 2>/dev/null; tesseract /app/prompts/frame_0061.png stdout --psm 7 2>/dev/null\n",
      "duration": 1.0
    }
  ]
}
